using System.Linq;using System;using System.Drawing;using System.Windows.Forms;using System.Reflection;using System.Collections.Generic;using AutosurBuscador;
class UiSmoke {
 static System.Collections.Generic.IEnumerable<Control> Walk(Control c){foreach(Control child in c.Controls){yield return child;foreach(var nested in Walk(child))yield return nested;}}
 static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,v);}
 [STAThread]static void Main(){Application.EnableVisualStyles();var page=new ObjetivosPage();var store=new SalesStore(System.IO.Path.Combine(System.IO.Path.GetTempPath(),"AutosurUi_"+Guid.NewGuid().ToString("N")));var p=new DateTime(2026,10,1);store.Set(new Snapshot{Period=p,Cutoff=new DateTime(2026,10,14),Loaded=DateTime.UtcNow,Lines=new List<SaleLine>{new SaleLine{Date=new DateTime(2026,10,14),Type="FACTURA DE VENTA",Code="F",Number="1",Sector="Taller",Sale=28000000,Profit=8400000},new SaleLine{Date=new DateTime(2026,10,14),Type="FACTURA DE VENTA",Code="F",Number="2",Sector="Mostrador",Sale=44000000,Profit=8800000}}});store.GetGoal(p).Total=60000000;store.CalendarYears.Add(2026);store.Holidays.Add(new DateTime(2026,10,12));Set(page,"store",store);((DateTimePicker)Get(page,"period")).Value=p;page.GetType().GetMethod("ResetDates",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(page,null);var form=new Form{Width=1450,Height=1050};form.Controls.Add(page);form.Show();Application.DoEvents();using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(0,0,bmp.Width,bmp.Height));bmp.Save("dashboard-verificado.png");}var projectionText=((Label)Get(page,"projection")).Text;if(!projectionText.Contains("120,00 %"))throw new Exception("No se mostró sobreperformance");Console.WriteLine(projectionText);Console.WriteLine("UI control created and rendered");form.Dispose();using(var main=new MainForm()){main.Show();Application.DoEvents();var all=Walk(main).ToArray();if(!all.OfType<TabPage>().Any(x=>x.Text=="Objetivos"))throw new Exception("Falta pestaña Objetivos");if(!all.OfType<Button>().Any(x=>x.Text=="Buscar actualizaciones")||!all.OfType<Button>().Any(x=>x.Text=="Acceso GitHub"))throw new Exception("Faltan botones de actualización");Console.WriteLine("OK pestañas originales, objetivos y botones de actualización");main.Close();}}
}
